def count_oper(x):
    if x == 1:
        return 0
    cnt = 0
    while x:
        cnt += x & 1
        x //= 2
    return count_oper(cnt) + 1

def solve(s, k):
    n = len(s)
    ones_idx = []
    for i, ch in enumerate(s):
        if ch == '1':
            ones_idx.append(i)
    nones = len(ones_idx)
    if k == 0:
        print(1)
        return
    if k == 1 and n != 1:
        print(n - 1)
        return
    if n == 1:
        print(0 if k > 0 else 1)
        return
    mod = 10**9 + 7
    C = [[0]*(n+1) for _ in range(n+1)]
    for i in range(n+1):
        C[i][0] = 1
        C[i][i] = 1
        for j in range(1, i):
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % mod
    ans = 0
    if s == "1" * n:
        rnge = range(1, n)
    else:
        rnge = range(1, n+1)
    for m in rnge:
        if count_oper(m) == k - 1:
            for j in range(min(nones, m)):
                ans = (ans + C[n - ones_idx[j] - 1][m - j]) % mod
            if nones >= m:
                ans = (ans + 1) % mod
    print(ans % mod)

if __name__ == '__main__':
    s = input().strip()
    k = int(input())
    solve(s, k)

