    res = 0
    for a in arr:
        res |= a
    return res

def simple_case(xk, arr):
    l0 = len(bin(arr[0] * xk))
    l1 = len(bin(arr[1] * xk))
    return l0 > l1

def complex_case(n, xk, arr, flag):
    l0 = len(bin(arr[0] * xk))
    idx = n
    r = 0
    for i, a in enumerate(arr[1:], 1):
        if len(bin(a * xk)) < l0:
            idx = i
            r = cumor(arr[i:])
            break
    ort = Ortree(idx, arr[:idx])
    best = r
    for i in range(idx):
        s = ort.upd(i, arr[i] * xk) | r
        if flag:
            s |= 1
        if best < s:
            best = s
        ort.upd(i, arr[i])
    return best

